//! Translation key registry — auto-generated from the rebuilt zh-CN language pack.
//!
//! Every key used by `t()` call sites is declared here as a Rust constant, grouped
//! by domain module (mirroring the FTL files under `assets/locales/`). Key IDs are
//! stable strings; the constant name is an uppercased, sanitized form.

/// Declare a domain module of key constants plus its `ALL` array.
macro_rules! define_keys {
    ($($name:ident = $key:literal),* $(,)?) => {
        $(pub const $name: &str = $key;)*
        /// Every key declared in this module.
        pub const ALL: &[&str] = &[$($key),*];
    };
}

